import { useMemo, useState } from 'react';
import { Link, useSearchParams } from 'react-router-dom';
import { ArrowUpRight, BookOpen, Download, GitBranch, Search, SlidersHorizontal } from 'lucide-react';
import { MISSING_PROGRAM_FILES, RESEARCH_PROGRAM as data } from '../data/researchProgram';
import { filterProgramConnections, findEvidencePaths, programExport, type ProgramConnection } from '../data/researchProgramSchema';
import ProgramNetwork from '../components/investigations/ProgramNetwork';
import { downloadProgramJson, ProgramSources, TextList } from '../components/investigations/ProgramEvidence';
import ProgramLeadPlan from '../components/investigations/ProgramLeadPlan';
import '../research-program.css';

const tabs = [{ id: 'network', title: 'Connection desk' }, { id: 'leads', title: 'Testable leads' }, { id: 'coverage', title: 'Coverage & gaps' }, { id: 'cases', title: 'Case comparisons' }, { id: 'methods', title: 'Methods library' }];
const human = (text: string) => text.replace(/-/g, ' ');
const unique = (items: string[]) => [...new Set(items)].sort();
const requestedThemes = [
  { title: 'Political funding', sectors: ['political-finance'] }, { title: 'PM CARES', sectors: ['pmcares', 'PM CARES'] },
  { title: 'BJP', sectors: ['bjp'] }, { title: 'RSS', sectors: ['rss'] }, { title: 'Foreign connections / transnational funds', sectors: ['foreign-influence'] },
  { title: 'Energy', sectors: ['energy'] }, { title: 'Oil', sectors: ['oil'] }, { title: 'Natural resources', sectors: ['natural-resources'] },
  { title: 'Welfare', sectors: ['welfare'] }, { title: 'Arms deals', sectors: ['defence-procurement'] }, { title: 'Police', sectors: ['police'] }, { title: 'Judiciary', sectors: ['judiciary'] },
];
const allSectors = unique([...data.coverage.map(row => row.sector), ...data.connections.flatMap(row => row.sectorIds ?? []), ...data.leads.flatMap(row => row.sectorIds)]);
const entityName = (id: string) => data.entities.find(entity => entity.id === id)?.name ?? id;

function ConnectionInspector({ connection }: { connection: ProgramConnection }) {
  const entities = data.entities.filter(entity => entity.id === connection.from || entity.id === connection.to);
  return <article className="rp-inspector" aria-label="Connection evidence inspector"><div className="rp-eyebrow">Selected relation · <span className={`rp-status ${connection.status}`}>{connection.status}</span></div><h2>{connection.label}</h2>
    <p className="rp-direction">{entityName(connection.from)} <span aria-label="to">→</span> {entityName(connection.to)}</p>
    <p>{connection.summary}</p><p className="rp-meta">Type: {human(connection.relation)} · {connection.dateFrom ?? 'start not specified'} → {connection.dateTo ?? 'end not specified'}</p>
    {connection.amount && <div className="rp-amount"><strong>{connection.amount.exactValue ?? connection.amount.value.toLocaleString()} {connection.amount.currency} · {connection.amount.unit}</strong><span>Stage: {connection.amount.stage}</span><p>{connection.amount.basis}</p>{connection.amount.rawText && <p>{connection.amount.rawText}</p>}<small>Source-specific amount; no cross-stage or cross-currency total.</small></div>}
    <h3>Limits of this relation</h3><TextList items={connection.limits} /><h3>Alternative explanations</h3><TextList items={connection.alternativeExplanations} /><h3>Test that could weaken the claim</h3><p>{connection.falsifier}</p><h3>Response / competing account</h3><p>{connection.response ?? 'No response recorded in this research slice. This is a collection gap, not a refusal to respond.'}</p>
    <ProgramSources ids={connection.sourceIds} sources={data.sources} />
    <details className="rp-identities"><summary>Endpoint identity and provenance</summary>{entities.map(entity => <div key={entity.id}><h4>{entity.name}</h4><p>{entity.type} · <code>{entity.id}</code></p><TextList items={entity.identifiers.length ? entity.identifiers : ['No additional identifier retained. Names are not used to merge records.']} />{entity.existingEntityId && <p>Reviewed registry crosswalk: <code>{entity.existingEntityId}</code></p>}<ProgramSources ids={entity.sourceIds} sources={data.sources} /></div>)}</details>
  </article>;
}

export default function ResearchProgram() {
  const [params, setParams] = useSearchParams(); const [page, setPage] = useState(0); const [pathFrom, setPathFrom] = useState(''); const [pathTo, setPathTo] = useState(''); const [direction, setDirection] = useState<'directed' | 'both'>('directed'); const [category, setCategory] = useState(''); const [notice, setNotice] = useState('');
  const active = tabs.some(tab => tab.id === params.get('tab')) ? params.get('tab')! : 'network';
  const filters = { sector: params.get('sector') ?? '', status: params.get('status') ?? '', relation: params.get('relation') ?? '', entity: params.get('entity') ?? '', query: params.get('q') ?? '' };
  const filtered = useMemo(() => filterProgramConnections(data, filters), [filters.sector, filters.status, filters.relation, filters.entity, filters.query]);
  const pageCount = Math.max(1, Math.ceil(filtered.length / 16)); const edgeIndex = filtered.findIndex(edge => edge.id === params.get('edge')); const safePage = edgeIndex >= 0 ? Math.floor(edgeIndex / 16) : Math.min(page, pageCount - 1); const visible = filtered.slice(safePage * 16, safePage * 16 + 16);
  const selected = filtered.find(edge => edge.id === params.get('edge')) ?? visible[0];
  const paths = useMemo(() => findEvidencePaths(filtered, pathFrom, pathTo, direction), [filtered, pathFrom, pathTo, direction]);
  const leads = data.leads.filter(lead => (!filters.sector || lead.sectorIds.includes(filters.sector)) && (!filters.query || `${lead.title} ${lead.question}`.toLowerCase().includes(filters.query.toLowerCase()))).sort((a, b) => ({ high: 0, medium: 1, low: 2 }[a.priority ?? 'low'] - { high: 0, medium: 1, low: 2 }[b.priority ?? 'low']));
  const update = (key: string, value: string) => { const next = new URLSearchParams(params); if (value) next.set(key, value); else next.delete(key); if (key !== 'edge' && key !== 'tab') { next.delete('edge'); setPage(0); } setParams(next, { replace: key === 'q' }); };
  const selectEdge = (id: string) => update('edge', id);
  const sourceFamilies = new Set(data.sources.map(source => source.sourceFamily)).size;
  return <article className="rp-desk" aria-label="Academic investigation research program">
    <nav className="rp-route-nav" aria-label="Investigation pages"><Link to="/investigations">Investigation network</Link><Link to="/leads">Unresolved leads</Link><Link to="/game-theory">Game theory lab</Link><span aria-current="page">Research program</span></nav>
    <header className="rp-hero"><div><p className="rp-eyebrow"><BookOpen size={14} aria-hidden="true" /> Public-records research program</p><h1>Follow a claim.<br /><em>Test every connection.</em></h1><p className="rp-deck">An investigation desk for political funding, public resources and institutional oversight. Trace the record, compare competing explanations, and make the next evidence request precise.</p><div className="rp-hero-links"><button className="rp-enter" onClick={() => { const content = document.getElementById('rp-content'); content?.focus(); content?.scrollIntoView({ block: 'start' }); }}>Enter the research desk <ArrowUpRight size={16} aria-hidden="true" /></button><button onClick={() => update('tab', 'coverage')}>Read the coverage gaps</button></div></div><aside className="rp-scope"><span className="rp-eyebrow">Retained research · not a population</span><dl><div><dt>Typed connections</dt><dd>{data.connections.length}</dd></div><div><dt>Cited records</dt><dd>{data.sources.length}</dd></div><div><dt>Source families</dt><dd>{sourceFamilies}</dd></div><div><dt>Testable leads</dt><dd>{data.leads.length}</dd></div></dl><p>Documents can establish an event or an allegation without establishing corruption. A path does not prove common intent.</p></aside></header>
    {data.errors.length > 0 && <section className="rp-error" role="alert"><h2>Research records failed validation</h2><p>The corpus is withheld until these schema or reference errors are corrected.</p><TextList items={data.errors} /></section>}
    {MISSING_PROGRAM_FILES.length > 0 && <p className="rp-boundary">Research slices not yet loaded: {MISSING_PROGRAM_FILES.join(', ')}. Missing material is not evidence of absence.</p>}
    <nav className="rp-tabs" aria-label="Research desk views">{tabs.map(tab => <button key={tab.id} onClick={() => update('tab', tab.id)} aria-current={active === tab.id ? 'page' : undefined}>{tab.title}</button>)}</nav>
    <section id="rp-content" className="rp-content" tabIndex={-1} aria-label={tabs.find(tab => tab.id === active)?.title}>
      {['network', 'leads'].includes(active) && <div className="rp-filters"><label><Search size={14} aria-hidden="true" /> Search recorded text<input aria-label="Search recorded text" value={filters.query} onChange={event => update('q', event.target.value)} placeholder="Entity, relation or question" /></label><label>Sector<select aria-label="Sector" value={filters.sector} onChange={event => update('sector', event.target.value)}><option value="">All researched sectors</option>{allSectors.map(sector => <option key={sector} value={sector}>{human(sector)}</option>)}</select></label>{active === 'network' && <><label>Status<select aria-label="Status" value={filters.status} onChange={event => update('status', event.target.value)}><option value="">All claim statuses</option>{['documented', 'alleged', 'hypothesis'].map(value => <option key={value}>{value}</option>)}</select></label><label>Relation<select aria-label="Relation" value={filters.relation} onChange={event => update('relation', event.target.value)}><option value="">All relation types</option>{unique(data.connections.map(edge => edge.relation)).map(value => <option key={value} value={value}>{human(value)}</option>)}</select></label><label>Endpoint entity<select aria-label="Endpoint entity" value={filters.entity} onChange={event => update('entity', event.target.value)}><option value="">All exact entities</option>{data.entities.map(entity => <option key={entity.id} value={entity.id}>{entity.name} · {entity.id}</option>)}</select></label></>}<button className="rp-reset" onClick={() => { setParams({ tab: active }); setPage(0); }}><SlidersHorizontal size={14} aria-hidden="true" /> Reset filters</button></div>}
      {active === 'network' && <><div className="rp-section-heading"><div><p className="rp-eyebrow">Relations retain their own evidentiary status</p><h2>The connection desk</h2><p><span className="rp-status documented">Documented</span> record-backed relation · <span className="rp-status alleged">Alleged</span> attributed claim · <span className="rp-status hypothesis">Hypothesis</span> testable proposal</p></div><button onClick={() => { downloadProgramJson('research-connections.json', programExport(data, filtered)); setNotice(`Exported ${filtered.length} filtered relations with endpoint identity records and citations.`); }}><Download size={15} aria-hidden="true" /> Export filtered records</button></div>
        <div className="rp-network-grid"><div><div className="rp-graph-bar"><span>{filtered.length} matching relations · drawing {visible.length}</span><div><button disabled={!safePage} onClick={() => { setPage(safePage - 1); update('edge', ''); }} aria-label="Previous relations">←</button><span>{safePage + 1} / {pageCount}</span><button disabled={safePage + 1 >= pageCount} onClick={() => { setPage(safePage + 1); update('edge', ''); }} aria-label="Next relations">→</button></div></div><ProgramNetwork entities={data.entities} connections={visible} selected={selected?.id ?? ''} onSelect={selectEdge} />
          <div className="rp-ledger" aria-label="Recorded relation ledger">{visible.map(edge => <button key={edge.id} onClick={() => selectEdge(edge.id)} aria-pressed={selected?.id === edge.id}><span className={`rp-status ${edge.status}`}>{edge.status}</span><strong>{edge.label}</strong><span>{entityName(edge.from)} → {entityName(edge.to)}</span><small>{human(edge.relation)} · {edge.sourceIds.length} cited records</small></button>)}</div></div>{selected ? <ConnectionInspector key={selected.id} connection={selected} /> : <aside className="rp-empty">Select a broader scope to inspect a recorded relation.</aside>}</div>
        <section className="rp-paths"><div className="rp-section-heading"><div><p className="rp-eyebrow"><GitBranch size={14} aria-hidden="true" /> Evidence path explorer</p><h2>Read each step, not a hidden conclusion.</h2><p>Search within the current filters, up to four recorded relations and three paths. Similar names never create an identity join. A path preserves each claim’s status; it does not establish coordination. Search does not enforce temporal overlap: a path can link different periods and is not evidence of a contemporaneous chain.</p></div></div><div className="rp-path-controls"><label>Path start<select aria-label="Path start" value={pathFrom} onChange={event => setPathFrom(event.target.value)}><option value="">Choose exact entity</option>{data.entities.map(entity => <option value={entity.id} key={entity.id}>{entity.name} · {entity.id}</option>)}</select></label><label>Path destination<select aria-label="Path destination" value={pathTo} onChange={event => setPathTo(event.target.value)}><option value="">Choose exact entity</option>{data.entities.map(entity => <option value={entity.id} key={entity.id}>{entity.name} · {entity.id}</option>)}</select></label><label>Traversal<select aria-label="Traversal" value={direction} onChange={event => setDirection(event.target.value as typeof direction)}><option value="directed">Follow recorded direction</option><option value="both">Either direction, mark reversed steps</option></select></label></div>
          {pathFrom && pathTo && !paths.paths.length && <p role="status">No path within the selected records and four-step search boundary. This does not establish that no connection exists.</p>}
          {paths.paths.map((path, index) => <article className="rp-path" key={index}><h3>Recorded path {index + 1}</h3><ol>{path.connectionIds.map((id, step) => { const edge = data.connections.find(item => item.id === id)!; return <li key={id}><button onClick={() => selectEdge(id)}>{entityName(path.entityIds[step])} → {entityName(path.entityIds[step + 1])}<strong>{edge.label}</strong></button><span className={`rp-status ${edge.status}`}>{edge.status}</span><p className="rp-meta">Recorded period: {edge.dateFrom ?? 'start unspecified'} → {edge.dateTo ?? 'end unspecified'}</p>{path.reversed[step] && <em> Traversed against the recorded arrow; relation direction is unchanged.</em>}<ProgramSources ids={edge.sourceIds} sources={data.sources} /></li>; })}</ol><button onClick={() => downloadProgramJson(`evidence-path-${index + 1}.json`, { ...programExport(data, data.connections.filter(edge => path.connectionIds.includes(edge.id))), traversal: path })}>Export this evidence path</button></article>)}{paths.truncated && <p className="rp-meta">Search stopped at the display or expansion bound. Other paths may exist.</p>}
        </section></>}
      {active === 'leads' && <><div className="rp-section-heading"><div><p className="rp-eyebrow">Questions that can lose</p><h2>Prioritize the next test.</h2><p>Priority is an editorial research choice, not a probability of wrongdoing. Every lead includes evidence that could weaken it.</p></div><button onClick={() => downloadProgramJson('research-leads.json', { schemaVersion: 1, exportedAt: new Date().toISOString(), boundary: 'Research priorities are not findings or probabilities.', leads, sources: data.sources.filter(source => leads.some(lead => lead.sourceIds.includes(source.id))) })}>Export filtered leads</button></div><div className="rp-leads">{leads.map(lead => <article key={lead.id} className="rp-lead"><div className="rp-eyebrow">{lead.sectorIds.map(human).join(' / ')} · {lead.priority ? `${lead.priority} research priority` : 'priority unranked'}</div><h2>{lead.title}</h2><p className="rp-question">{lead.question}</p><div className="rp-two-col"><div><h3>Evidence needed</h3><TextList items={lead.neededEvidence} /></div><div><h3>Disconfirming evidence</h3><TextList items={lead.disconfirmingEvidence} /></div></div><h3>Feasibility</h3><p>{lead.feasibility}</p><ProgramSources ids={lead.sourceIds} sources={data.sources} /><ProgramLeadPlan lead={lead} sources={data.sources} allowedKeys={data.leads.map(row => row.id)} /></article>)}</div>{!leads.length && <p className="rp-empty">No leads match these filters.</p>}</>}
      {active === 'coverage' && <><div className="rp-section-heading"><div><p className="rp-eyebrow">Known scope and missing records</p><h2>Coverage is an inventory, not a verdict.</h2><p>Inspected-source counts describe retained work. They are not the size of a sector or an exhaustive population, and repeated source families may overlap.</p></div></div><p id="rp-coverage-scroll-help" className="rp-table-hint">More columns are available horizontally. Swipe the table, or focus it and use the left and right arrow keys.</p><div className="rp-table-wrap" role="region" aria-label="Sector research coverage table" aria-describedby="rp-coverage-scroll-help" tabIndex={0}><table><caption>Sector research coverage</caption><thead><tr><th>Sector</th><th>Research status</th><th>Inspected sources</th><th>Remaining acquisition / verification gaps</th></tr></thead><tbody>{data.coverage.map((row, i) => <tr key={`${row.sector}-${i}`}><th scope="row">{human(row.sector)}</th><td>{human(row.status)}</td><td>{row.inspectedSources}</td><td><TextList items={row.remainingGaps} /></td></tr>)}</tbody></table></div><details className="rp-uninspected" open><summary>Requested themes and the limits of related coverage</summary><p>Theme labels group related sector records. Foreign-influence coverage consists of selected disclosures; it does not establish a complete transnational funding picture or full BJP / RSS coverage.</p><div className="rp-theme-coverage">{requestedThemes.map(theme => { const matching = data.coverage.filter(row => theme.sectors.includes(row.sector)); return <div key={theme.title}><strong>{theme.title}</strong><span>{matching.length ? `Related coverage: ${unique(matching.map(row => human(row.sector))).join(', ')}. Read acquisition gaps above.` : 'No separate coverage assessment in this batch. Related mentions are not a complete inquiry.'}</span></div>; })}</div></details></>}
      {active === 'cases' && <><div className="rp-section-heading"><div><p className="rp-eyebrow">Historical comparison</p><h2>Borrow the test, not the accusation.</h2><p>These cases illustrate evidence chains and legal outcomes. Analogies are not evidence against current actors; findings remain specific to the subject, date and legal stage shown.</p></div></div><div className="rp-comparisons">{data.cases.map(item => <article key={item.id}><p className="rp-eyebrow">{item.sectors.map(human).join(' / ')}</p><h2>{item.title}</h2><p>{item.mechanism}</p><h3>Evidentiary chain</h3><ol>{item.evidentiaryChain.map((step, i) => <li key={i}>{typeof step === 'string' ? step : <><strong>{step.stage}</strong><p>{step.evidence}</p><p><strong>Permitted inference:</strong> {step.inferenceAllowed}</p><p><strong>Inference limit:</strong> {step.inferenceNotAllowed}</p><p className="rp-meta">Locator: {step.locator}</p><ProgramSources ids={step.sourceIds} sources={data.sources} /></>}</li>)}</ol><div className="rp-legal"><h3>{item.legalOutcome.stage} · {item.legalOutcome.date}</h3><p><strong>Subject:</strong> {item.legalOutcome.subject}</p><p>{item.legalOutcome.finding}</p><p className="rp-boundary">{item.legalOutcome.limits}</p></div><h3>Transferable research tests</h3><div className="rp-transferable">{item.transferableTests.map((test, i) => typeof test === 'string' ? <p key={i}>{test}</p> : <details key={test.id}><summary>{test.question}</summary><p className="rp-meta">{test.status}</p><h4>Required records</h4><TextList items={test.requiredRecords} /><p><strong>Comparator:</strong> {test.comparator}</p><p><strong>Rival explanation:</strong> {test.rivalExplanation}</p><p><strong>Falsifier:</strong> {test.falsifier}</p><p className="rp-boundary"><strong>Stop rule:</strong> {test.stopRule}</p></details>)}</div><h3>Inferences that do not transfer</h3><TextList items={item.nonTransferableInferences} /><ProgramSources ids={item.sourceIds} sources={data.sources} /></article>)}</div></>}
      {active === 'methods' && <><div className="rp-section-heading"><div><p className="rp-eyebrow">A reproducible investigation workflow</p><h2>Methods, with their failure modes.</h2><p>Prompts and agents propose work. Sources, explicit joins and review establish what survives. Method status is not a comparative performance ranking.</p></div><label>Method category<select aria-label="Method category" value={category} onChange={event => setCategory(event.target.value)}><option value="">All categories</option>{unique(data.methods.map(method => method.category)).map(value => <option key={value}>{value}</option>)}</select></label></div><div className="rp-methods">{data.methods.filter(method => !category || method.category === category).map(method => <article key={method.id}><p className="rp-eyebrow">{method.category} · {method.status}</p><h2>{method.title}</h2><p>{method.purpose}</p><details open><summary>Procedure</summary><ol>{method.steps.map((step, i) => <li key={i}>{step}</li>)}</ol></details><h3>Required outputs</h3><TextList items={method.requiredOutputs} /><h3>Failure modes</h3><TextList items={method.failureModes} /><p className="rp-boundary">{method.benchmarkLimits}</p><ProgramSources ids={method.sourceIds} sources={data.sources} /></article>)}</div></>}
    </section><p className="rp-live" role="status">{notice}</p><footer className="rp-footer">This desk records a bounded research program. Source families, read depth, unresolved gaps and competing explanations travel with the claims. Exported records preserve those limits.</footer>
  </article>;
}
